<template><el-button v-if="canImport" :disabled="busy" @click="open">导入草稿JSON</el-button><el-button v-if="canExport" :disabled="!selected.length||busy" @click="exportRows">导出选中草稿</el-button><el-dialog v-model="visible" title="导入新增草稿（不会自动发布或覆盖）" width="min(950px,calc(100vw - 32px))" append-to-body :close-on-click-modal="false" @closed="close"><el-alert title="每批1—20条，JSON最多1MiB。先下载模板；栏目和素材ID属于当前门户库，文件不包含图片。所有导入只新增草稿，已有地址（含历史删除）不能重复使用。" :closable="false"/><p><el-button @click="template">下载JSON模板</el-button><input type="file" :disabled="busy" accept=".json,application/json" aria-label="选择草稿JSON文件" @change="read"/></p><el-input :disabled="busy" v-model="text" type="textarea" :rows="10" placeholder="可粘贴或修改模板JSON；修改后须重新预检查"/><p><el-button :loading="busy" @click="check">预检查，不写入</el-button><el-button type="primary" :disabled="!checked||!ready||applied" :loading="busy" @click="apply">导入通过检查的行</el-button></p><el-alert v-if="result" :title="result.checkOnly?`预检查：可导入${ready}行，有问题${result.failureCount}行；尚未写入`:`导入：成功${result.successCount}行，失败${result.failureCount}行；成功项只是草稿`" :closable="false"/><el-table :data="result?.rows||[]"><el-table-column prop="row" label="行号" width="65"/><el-table-column prop="slug" label="地址" min-width="170" show-overflow-tooltip/><el-table-column prop="contentId" label="新增内容ID" width="105"/><el-table-column prop="message" label="结果 / 原因" min-width="260"/></el-table><template #footer><el-button @click="visible=false">关闭</el-button></template></el-dialog></template>
<script setup>
import{ref,computed,watch,onDeactivated,onBeforeUnmount}from'vue';import{ElMessage,ElMessageBox}from'element-plus';import auth from'@/plugins/auth';import request from'@/utils/request';const props=defineProps({kind:String,selected:{type:Array,default:()=>[]}}),emit=defineEmits(['changed']),visible=ref(false),text=ref(''),busy=ref(false),result=ref(),checked=ref(false),applied=ref(false);const canImport=computed(()=>auth.hasPermiAnd([`cms:${props.kind}:import`,`cms:${props.kind}:add`])),canExport=computed(()=>auth.hasPermiAnd([`cms:${props.kind}:export`,`cms:${props.kind}:query`])),ready=computed(()=>result.value?.rows.filter(x=>x.ready).length||0);let epoch=0;watch(text,()=>{checked.value=false;applied.value=false;result.value=null});function open(){++epoch;visible.value=true;text.value='';result.value=null;checked.value=false;applied.value=false}function close(){++epoch;visible.value=false;text.value='';result.value=null;checked.value=false}function download(data,name){const u=URL.createObjectURL(new Blob([JSON.stringify(data)],{type:'application/json;charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}async function template(){const n=epoch;const r=await request({url:`/cms/${props.kind}/transfer/template`});if(n===epoch&&visible.value)download(r.data,`cms-${props.kind}-template.json`)}async function read(e){const f=e.target.files?.[0];if(!f)return;if(f.size>1048576){ElMessage.warning('文件最多1MiB');e.target.value='';return}const n=epoch;const value=await f.text();if(n===epoch&&visible.value)text.value=value;e.target.value=''}function payload(){if(new TextEncoder().encode(text.value).length>1048576)throw new Error('JSON最多1MiB');return JSON.parse(text.value)}async function check(){if(busy.value)return;let data;try{data=payload()}catch(e){ElMessage.warning(e.message||'JSON格式错误');return}const n=epoch,snapshot=text.value;busy.value=true;try{const r=await request({url:`/cms/${props.kind}/transfer/check`,method:'post',data,timeout:60000});if(n===epoch&&visible.value&&text.value===snapshot){result.value=r.data;checked.value=true;applied.value=false}}finally{busy.value=false}}async function apply(){if(busy.value||!checked.value||applied.value)return;const n=epoch,snapshot=text.value;try{await ElMessageBox.confirm('只新增预检查通过的行，逐行保存，可能部分成功；不会发布。确认导入？','导入草稿');if(n!==epoch||!visible.value||text.value!==snapshot)return;busy.value=true;const r=await request({url:`/cms/${props.kind}/transfer/import`,method:'post',data:payload(),timeout:60000});if(n!==epoch||!visible.value)return;result.value=r.data;checked.value=false;applied.value=true;emit('changed')}catch{}finally{busy.value=false}}async function exportRows(){if(busy.value)return;if(props.selected.length>20){ElMessage.warning('每次最多导出20条');return}const n=epoch;const items=props.selected.map(x=>({contentId:x.contentId,version:x.version}));busy.value=true;try{const r=await request({url:`/cms/${props.kind}/transfer/export`,method:'post',data:{items},timeout:60000});if(n===epoch)download(r.data,`cms-${props.kind}-drafts.json`)}finally{busy.value=false}}onDeactivated(close);onBeforeUnmount(close)
</script>
